import json, os, csv

T = "/task"
names = set(os.listdir(T))
res = {}

def rows(fn):
    with open(os.path.join(T, fn), newline="") as fh:
        return list(csv.DictReader(fh))

if "blot_p21_intensities.csv" in names:
    d = {}
    for r in rows("blot_p21_intensities.csv"):
        d[(r["condition"], r["protein"])] = float(r["raw_intensity"])
    def norm(c):
        return d[(c, "p21")] / d[(c, "GAPDH")]
    res["fold_change_drug_a"] = norm("Drug_A") / norm("Control")
    res["fold_change_drug_b"] = norm("Drug_B") / norm("Control")

if "smad_blot_intensities.csv" in names:
    d = {}
    for r in rows("smad_blot_intensities.csv"):
        d[(r["condition"], r["protein"])] = float(r["raw_intensity"])
    def modsig(c):
        lc = d[(c, "GAPDH")]
        psmad_norm = d[(c, "PSMAD2")] / lc
        smad_norm = d[(c, "SMAD2")] / lc
        return psmad_norm / smad_norm
    base = modsig("Control")
    res["psmad2_fold_tgfb1"] = modsig("TGFb1") / base
    res["psmad2_fold_p144"] = modsig("P144") / base
    res["psmad2_fold_tb1ab"] = modsig("Tb1Ab") / base

if "hif1a_stainfree_blot.csv" in names:
    d = {}
    for r in rows("hif1a_stainfree_blot.csv"):
        d[r["condition"]] = float(r["HIF1A_band_density"]) / float(r["total_protein_lane_density"])
    res["hif1a_fold_hypoxia_2h"] = d["Hypoxia_2h"] / d["Normoxia"]
    res["hif1a_fold_hypoxia_8h"] = d["Hypoxia_8h"] / d["Normoxia"]
    res["hif1a_fold_reoxygenation"] = d["Reoxygenation"] / d["Normoxia"]

if "akt_signalling_blot.csv" in names:
    d = {}
    for r in rows("akt_signalling_blot.csv"):
        lc = float(r["beta_actin"])
        d[r["condition"]] = (float(r["pAKT_S473"]) / lc) / (float(r["AKT_total"]) / lc)
    res["pakt_fold_insulin_5min"] = d["Insulin_5min"] / d["Vehicle"]
    res["pakt_fold_insulin_30min"] = d["Insulin_30min"] / d["Vehicle"]
    res["strongest_condition"] = max(d, key=lambda c: d[c])

with open("/work/results.json", "w") as fh:
    json.dump(res, fh)
